const api = game.modules.get('pf2e-trooper')?.api;
const seen = new Set();
for (const token of canvas.tokens.controlled) {
  // Segments of one troop are one unit: recover it once, however many are selected.
  const key = token.document.flags?.pf2e?.troop?.id ?? token.actor?.id;
  if (!token.actor || !key || seen.has(key)) continue;
  seen.add(key);
  const before = api?.reducedStatus(token.actor);
  if (before === null) continue;
  if (before === 4) {
    ui.notifications.info(game.i18n.format('pf2e-trooper.troopReduced.notReduced', { name: token.name }));
    continue;
  }
  await api?.recoverOneSegment(token.actor);
}
if (seen.size === 0) ui.notifications.warn(game.i18n.localize('pf2e-trooper.troopReduced.selectTroop'));
